function expDefaultWorld(mode,seed){const cfg=expeditionModes[mode],x=140,cell=Math.floor(x/40),y=['forest','sky','cave'].includes(mode)?expeditionSurface(seed,cell,mode)*40:cfg.spawn[1];return {seed,x,y,fly:cfg.fly,vy:0,dug:[],ladders:[],found:[],seen:[],bands:[],plots:{},blocks:{},tool:'explore',harvested:[],mission:0,route:[],pending:null,motion:null,selectedPlot:null,last:null,gripping:false};}
export function normalizeExpeditions(raw={}){const r=raw&&typeof raw==='object'?raw:{},seed=Number.isInteger(r.seed)?r.seed>>>0:2063,s={seed,active:Object.hasOwn(expeditionModes,r.active)?r.active:null,worlds:{}};for(const mode of Object.keys(expeditionModes)){const q=r.worlds?.[mode],w=expDefaultWorld(mode,Number.isInteger(q?.seed)?q.seed>>>0:expeditionHash(seed,Object.keys(expeditionModes).indexOf(mode)));if(q&&typeof q==='object'){w.x=Number.isFinite(q.x)?expClamp(q.x,-1e12,1e12):w.x;w.y=Number.isFinite(q.y)?(mode==='farm'?expClamp(q.y,-1e12,1e12):expClamp(q.y,40,expeditionModes[mode].height*40-40)):w.y;w.fly=mode==='ocean'?false:typeof q.fly==='boolean'?q.fly:w.fly;for(const key of ['dug','ladders'])w[key]=[...new Set((Array.isArray(q[key])?q[key]:[]).filter(k=>typeof k==='string'&&/^-?\d{1,12},-?\d{1,12}$/.test(k)))].slice(-12000);w.found=[...new Set((Array.isArray(q.found)?q.found:[]).filter(k=>typeof k==='string'&&k.length<90))].slice(-800);w.seen=(Array.isArray(q.seen)?q.seen:[]).filter(o=>o&&Object.hasOwn(expeditionItems,o.type)&&typeof o.id==='string'&&Number.isFinite(o.x)&&Number.isFinite(o.y)).slice(-160).map(o=>({id:o.id,type:o.type,x:o.x,y:o.y,seed:farmPlants.some(p=>p.id===o.seed)?o.seed:null}));w.bands=[...new Set((Array.isArray(q.bands)?q.bands:[]).filter(i=>Number.isInteger(i)&&i>=0&&i<expeditionBands[mode].length))];w.mission=Number.isInteger(q.mission)?expClamp(q.mission,0,3):0;w.tool=['explore','block','platform','ladder','remove'].includes(q.tool)?q.tool:'explore';for(const [key,type]of Object.entries(q.blocks&&typeof q.blocks==='object'?q.blocks:{}).slice(-2048))if(/^-?\d{1,12},-?\d{1,12}$/.test(key)&&['block','platform','ladder'].includes(type))w.blocks[key]=type;w.harvested=[...new Set((Array.isArray(q.harvested)?q.harvested:[]).filter(id=>farmPlants.some(p=>p.id===id)))];for(const [key,p]of Object.entries(q.plots&&typeof q.plots==='object'?q.plots:{}).slice(-1024)){if(!/^-?\d{1,12},-?\d{1,12}$/.test(key)||!farmPlants.some(f=>f.id===p?.seed))continue;w.plots[key]={seed:p.seed,stage:[0,1,2,3].includes(p.stage)?p.stage:0,watered:p.stage<3&&p.watered===true,harvested:p.harvested===true};}}s.worlds[mode]=w;}return s;}
export function expeditionBand(mode,y){const row=y/40,list=expeditionBands[mode];return Math.max(0,list.findIndex(([,a,b])=>row>=a&&row<b));}
function expSets(w){if(!w._dug)w._dug=new Set(w.dug);if(!w._ladders)w._ladders=new Set(w.ladders);}
