export function expeditionCamera(w,mode){return {x:w.x-500,y:mode==='farm'?w.y-215:expClamp(w.y-215,0,expeditionModes[mode].height*40-425)};}
export function expeditionVisibleCells(w,mode){const c=expeditionCamera(w,mode),x0=Math.floor(c.x/40),y0=Math.floor(c.y/40),out=[];for(let y=y0;y<=y0+11;y++)for(let x=x0;x<=x0+25;x++)out.push({x,y,sx:x*40-c.x,sy:y*40-c.y+95,...expeditionCell(w,mode,x,y)});return out;}
function expFootCell(w){return [Math.floor(w.x/40),Math.floor((w.y-1)/40)];}
function expStand(w,mode,x,y){if(mode==='farm')return !expeditionCell(w,mode,x,y).solid;const t=expeditionCell(w,mode,x,y),below=expeditionCell(w,mode,x,y+1);return (!t.solid||mode==='cave')&&(below.solid||below.platform||t.climb||mode==='cave'&&t.solid);}
function expSnap(w,mode,x,y){const max=mode==='farm'?Infinity:expeditionModes[mode].height-2;y=mode==='farm'?y:expClamp(y,1,max);if(w.fly||mode==='ocean'||mode==='farm'){for(let r=0;r<=5;r++)for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++)if(!expeditionCell(w,mode,x+dx,y+dy).solid||mode==='cave')return [x+dx,y+dy];return null;}let candidates=[];for(let dy=-3;dy<=8;dy++)for(let dx=-3;dx<=3;dx++)if(expStand(w,mode,x+dx,y+dy))candidates.push([x+dx,y+dy]);return candidates.sort((a,b)=>Math.hypot(a[0]-x,a[1]-y)-Math.hypot(b[0]-x,b[1]-y))[0]||null;}
