export function expeditionRequest(s,point,pending=null){const mode=s.active,w=s.worlds[mode];w.route=expeditionPath(w,mode,point);w.motion=null;w.pending=pending;w.lastPoint={x:point.x,y:point.y};return w.route.length>0||Math.hypot(w.x-point.x,w.y-point.y)<65;}
