export function expeditionTick(s,dt){if(!s.active)return {};dt=Math.min(.05,Math.max(0,dt));const mode=s.active,w=s.worlds[mode],cfg=expeditionModes[mode];let changed=false,arrived=null;const oldPosition=[w.x,w.y],flying=w.fly||mode==='ocean'||mode==='farm';if(w.route.length&&!w.motion){const p=w.route[0],[cx,cy]=[Math.floor(p.x/40),Math.floor((p.y-1)/40)];if(mode==='cave'){expDig(w,cx,cy,!w.fly&&p.y<w.y-8);changed=true;}const climb=!flying&&(expeditionCell(w,mode,...expFootCell(w)).climb||expeditionCell(w,mode,cx,cy).climb),dy=p.y-w.y,dx=p.x-w.x,duration=flying?Math.max(.08,Math.hypot(dx,dy)/240):climb?Math.max(.12,Math.hypot(dx,dy)/150):dy>1?Math.max(.12,Math.sqrt(2*dy/EXP_GRAVITY)):Math.abs(dy)<1&&Math.abs(dx)<=45?Math.max(.12,Math.abs(dx)/170):Math.max(.28,Math.abs(dx)/170,Math.sqrt(8*Math.max(55,-dy+30)/EXP_GRAVITY));w.motion={from:[w.x,w.y],to:[p.x,p.y],time:0,duration,kind:flying?'fly':climb?'climb':dy>1?'fall':Math.abs(dy)<1&&Math.abs(dx)<=45?'walk':'hop'};w.gripping=climb;}
 if(w.motion){const m=w.motion;m.time+=dt;const t=Math.min(1,m.time/m.duration),lift=m.kind==='hop'?EXP_GRAVITY*m.duration*m.duration/8:0;w.x=m.from[0]+(m.to[0]-m.from[0])*t;w.y=m.from[1]+(m.to[1]-m.from[1])*(m.kind==='fall'?t*t:t)-4*lift*t*(1-t);w.vy=0;if(t===1){w.motion=null;w.route.shift();if(!w.route.length){arrived=w.pending;w.pending=null;changed=true;}}}else if(!flying){const [x,y]=expFootCell(w),at=expeditionCell(w,mode,x,y),under=expeditionCell(w,mode,x,y+1);if(!(at.climb&&w.gripping)&&!(Math.abs(w.y-(y+1)*40)<1&&(under.solid||under.platform))){const old=w.y;w.vy=Math.min(600,w.vy+EXP_GRAVITY*dt);const ny=w.y+w.vy*dt;let landed=false;for(let row=Math.floor(old/40);row<=Math.floor(ny/40);row++){const t=expeditionCell(w,mode,x,row);if((t.solid||t.platform)&&old<=row*40+.5){w.y=row*40;w.vy=0;landed=true;break;}}if(!landed)w.y=ny;}else w.vy=0;}
 if(!w.route.length&&!w.motion&&w.pending&&w.lastPoint&&Math.hypot(w.x-w.lastPoint.x,w.y-w.lastPoint.y)<75){arrived=w.pending;w.pending=null;changed=true;}if(mode!=='farm')w.y=expClamp(w.y,40,cfg.height*40-45);const band=expeditionBand(mode,w.y);if(!w.bands.includes(band)){w.bands.push(band);changed=true;}if(w.mission===1&&expMissionDeep(mode,w.y)){w.mission=2;changed=true;}changed=changed||w.x!==oldPosition[0]||w.y!==oldPosition[1];return {changed,arrived};}
function expItemPoint(w,mode,x,y){for(let k=0;k<6;k++){const t=expeditionCell(w,mode,x+k,y);if(!t.solid||mode==='cave')return [x+k,y];}return [x,y];}
export function expeditionChunkItems(w,mode,chunk){const seed=expeditionHash(w.seed,chunk,5),base=chunk*EXP_CHUNK,out=[],add=(type,x,y,extra={})=>{[x,y]=expItemPoint(w,mode,x,y);out.push({id:mode+':'+w.seed+':'+x+':'+y+':'+type,type,x:x*40+20,y:(y+1)*40,...extra});};if(mode==='sky'){add('balloon',base+4,103);add('meteor',base+11,61);add('satellite',base+8,31);}if(mode==='ocean'){add('dolphin',base+4,13);add('fish',base+11,31);add('octopus',base+4,65);add('giant',base+11,101);}if(mode==='cave'){add('fossil',base+4,28);add('dinosaur',base+12,35);add('quartz',base+11,52);add('cavelife',base+4,72);add('iron',base+11,96);add('mantle',base+8,123);}if(mode==='forest'){const tree=base+5-expMod(base+5,10)+5,top=17+expeditionHash(w.seed,Math.floor(tree/10),0)%4;add('seed',tree,top+1,{seed:['oak','apple','sunflower'][seed%3]});add('seed',base+11,expeditionSurface(w.seed,base+11,mode)-1,{seed:['bean','marigold','lavender'][seed%3]});}if(mode==='farm'&&(!w.colony||w.colony.kind==='home'))add('seed',base+7,11,{seed:['carrot','bean','tomato'][seed%3]});const x=base+2,y=['sky','cave','forest'].includes(mode)?expeditionSurface(w.seed,x,mode)-1:mode==='ocean'?10:11;add('camp',x,y);return out;}
export function expeditionVisibleItems(s){const mode=s.active,w=s.worlds[mode],c=expeditionCamera(w,mode),chunk=Math.floor(w.x/(EXP_CHUNK*40)),out=[];for(let k=chunk-2;k<=chunk+2;k++)for(const item of expeditionChunkItems(w,mode,k)){const sx=item.x-c.x,sy=item.y-c.y+95;if(sx>=65&&sx<=935&&sy>=165&&sy<=455)out.push({...item,sx,sy});}return out.sort((a,b)=>Math.hypot(a.sx-500,a.sy-315)-Math.hypot(b.sx-500,b.sy-315)).slice(0,8);}
export function expeditionInteract(s,item){const w=s.worlds[s.active],data=expeditionItems[item.type],fresh=!w.found.includes(item.id);if(item.type==='camp'){if(w.mission===2)w.mission=3;return {message:w.mission===3?'Trail mission complete. You can repeat it or keep exploring.':'PIP camp. We can explore freely or follow one small goal.'};}if(fresh){w.found.push(item.id);w.found=w.found.slice(-800);w.seen.push({id:item.id,type:item.type,x:item.x,y:item.y,seed:item.seed||null});w.seen=w.seen.slice(-160);}w.last=item;if(w.mission===0&&(['sky','ocean','cave','forest'].includes(s.active)))w.mission=1;return {message:(fresh?'Discovered: ':'Look again: ')+(item.seed?farmPlants.find(p=>p.id===item.seed)?.name+' seed':data.name),effect:fresh?{material:data.material,life:data.life,seed:item.seed||null}:null};}
export function expeditionGoal(s){const mode=s.active,w=s.worlds[mode],chunk=Math.floor(w.x/(EXP_CHUNK*40));if(w.mission===0){if(mode==='farm'){const [cx,cy]=expFootCell(w);for(let r=0;r<7;r++)for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++)if(expeditionCell(w,mode,cx+dx,cy+dy).plantable)return {text:'Plant one owned seed in a soil bed.',point:{x:(cx+dx)*40+20,y:(cy+dy)*40+20},plot:expKey(cx+dx,cy+dy)};return {text:'Find a brown planting bed.',point:null};}const type={sky:'balloon',ocean:'fish',cave:'fossil',forest:'seed'}[mode],item=expeditionChunkItems(w,mode,chunk).find(i=>i.type===type);return {text:'Find '+(type==='seed'?'a seed':expeditionItems[type].name.toLowerCase())+'.',point:item,item};}if(w.mission===1){if(mode==='farm'){const entry=Object.entries(w.plots).find(([,p])=>!p.harvested);if(entry){const [x,y]=entry[0].split(',').map(Number),p=entry[1];return {text:p.stage===3?'Harvest your grown plant.':p.watered?'Explore another world, then return to see a new growth stage.':'Water your planted seed.',point:p.watered?null:{x:x*40+20,y:y*40+20},plot:entry[0]};}return {text:'Plant and water a seed.',point:null};}const row={sky:31,ocean:101,cave:123,forest:9}[mode];return {text:{sky:'Visit the orbital view in the thermosphere.',ocean:'Visit the abyss.',cave:'Visit the protected mantle model.',forest:'Fly above the canopy.'}[mode],point:{x:w.x,y:row*40+20},flight:mode==='forest'};}if(w.mission===2){const item=expeditionChunkItems(w,mode,chunk).find(i=>i.type==='camp');return {text:'Return to the PIP camp beacon.',point:item,item,flight:mode==='sky'||mode==='forest'};}return {text:'Your trail is complete. Explore freely or repeat the mission.',point:null};}
export function expeditionTravel(s,point,{item=null,fly=false}={}){const w=s.worlds[s.active];if(fly&&s.active!=='ocean')w.fly=true;return expeditionRequest(s,point,item?{kind:'item',item}:null);}
export function expeditionAction(s,a,ctx={}){let route=a.route||'home',message='',effect=null,exit=false,worldChanged=false;if(a.type==='enter'&&expeditionEnter(s,a.mode)){route=null;worldChanged=true;message=expeditionModes[a.mode].name+'. Tap a destination. PIP can help.';}if(a.type==='exit'){s.active=null;exit=true;}if(!s.active)return {s,route,message,effect,exit,worldChanged};const mode=s.active,w=s.worlds[mode];if(a.type==='flight'){expeditionToggleFlight(s);route=null;message=mode==='ocean'?'Swim assistance stays on.':w.fly?'Backpack wings and boosters deployed.':'Backpack folded. Gravity and automatic climbing are active.';}if(a.type==='goal'){w.tool='explore';const goal=expeditionGoal(s);if(goal.point){expeditionTravel(s,goal.point,{item:goal.item,fly:goal.flight});if(goal.plot)w.pending={kind:'plot',key:goal.plot};route=null;message=goal.text;}else route=mode==='farm'?'home':'mission';}if(a.type==='step'){const step=8*40,p={x:w.x+(a.dx||0)*step,y:w.y+(a.dy||0)*step};if(mode==='farm'&&a.dy)p.y=w.y+a.dy*step;const ok=expeditionRequest(s,p);route=null;message=ok?'Traveling automatically. Tap another destination whenever you like.':'Choose an open space or ask PIP for a route.';}if(a.type==='band'){const band=expeditionBands[mode][a.index];if(band){const row=mode==='farm'?w.y/40:(band[1]+band[2])/2;let dest=expSnap(w,mode,Math.floor(w.x/40),Math.floor(row));if(mode==='sky'||mode==='forest'&&a.index===0){w.fly=true;dest=expSnap(w,mode,Math.floor(w.x/40),Math.floor(row));}if(dest){w.x=dest[0]*40+20;w.y=(dest[1]+1)*40;if(mode==='cave')expDig(w,dest[0],dest[1],true);w.route=[];w.motion=null;w.pending=null;w.vy=0;w.gripping=mode==='cave';}route=null;message='PIP lift: '+band[0]+'. '+band[3];}}if(a.type==='trail'){w.x=(Math.floor(w.x/(EXP_CHUNK*40))+2)*EXP_CHUNK*40+140;w.y=mode==='farm'?w.y:['cave','forest','sky'].includes(mode)?expeditionSurface(w.seed,Math.floor(w.x/40),mode)*40:440;w.route=[];w.pending=null;w.motion=null;w.vy=0;route=null;message='Another generated trail. Earlier discoveries stay in your journal.';}if(a.type==='repeat'){w.mission=0;route='mission';}if(a.type==='tool'&&['explore','block','platform','ladder','remove'].includes(a.id)){w.tool=a.id;route=null;message=a.id==='explore'?'Exploration tools ready.':'Tap a clear block cell to '+(a.id==='remove'?'remove your own block.':'place a '+a.id+'.');}if(a.type==='inspect'){route='last';}if(a.type==='plot'){w.selectedPlot=a.key;route='plot';}if(a.type==='plant'){const p=ctx.plants?.find(p=>p.id===a.seed);if(mode==='farm'&&w.selectedPlot&&p&&(w.plots[w.selectedPlot]||Object.keys(w.plots).length<1024)&&(!w.plots[w.selectedPlot]||w.plots[w.selectedPlot].stage===3)){w.plots[w.selectedPlot]={seed:a.seed,stage:0,watered:false,harvested:false};if(w.mission===0)w.mission=1;message='Planted. Water this bed, then explore and return.';}route='plot';}if(a.type==='water'){const p=w.plots[w.selectedPlot];if(p&&p.stage<3)p.watered=true;message='Watered. This plant grows one stage when you return to this farm.';route='plot';}if(a.type==='harvest'){const p=w.plots[w.selectedPlot];if(p?.stage===3){p.harvested=true;if(!w.harvested.includes(p.seed))w.harvested.push(p.seed);effect={harvest:p.seed};if(w.mission===1)w.mission=2;message='Harvest kept. Replant or leave your grown plant here.';}route='plot';}return {s,route,message,effect,exit,worldChanged};}
export function expeditionView(s,route='home',ctx={}){const [page,arg='0']=route.split(':'),w=s.active?s.worlds[s.active]:null,go=(label,route)=>({label,type:'page',route}),v=(title,text,actions)=>({title,text,actions});if(page==='home')return v('Big exploration worlds','Choose a generated world. Terrain continues as you travel. All astronauts can use backpack flight. These worlds are not to scale.',Object.entries(expeditionModes).map(([mode,m])=>({label:m.icon+' '+m.name,type:'enter',mode})));if(!w)return expeditionView(s,'home',ctx);if(page==='mission'){const g=expeditionGoal(s);return v('PIP / One trail goal',g.text+' You can explore freely at any time.',[...(g.point?[{label:'▶ Show me this goal',type:'goal'}]:[go('🌱 Farm help','farm-help')]),go('↕ World layers','bands:0'),{label:'↻ Repeat this trail mission',type:'repeat'},go('🌍 Choose a world','home'),{label:'🏠 Return home',type:'exit'}]);}if(page==='options')return v('My exploration trail','Keep exploring or visit a new stretch. Returning to a world keeps its discoveries, excavations and planted beds.',[{label:'→ Another generated trail',type:'trail'},go('🧱 Place / remove blocks','build'),go('🌍 Choose a world','home'),{label:'🛠 My Machines',type:'machines'},go('🤖 PIP mission','mission')]);if(page==='build')return v('Tap-to-build blocks','Choose a support, platform or ladder. Tap a cell to place it. Remove only your own pieces. Return to Explore to walk and inspect.',[{label:'🧱 Support block',type:'tool',id:'block'},{label:'━ Platform',type:'tool',id:'platform'},{label:'≋ Ladder',type:'tool',id:'ladder'},{label:'↶ Remove my block',type:'tool',id:'remove'},{label:'👆 Explore again',type:'tool',id:'explore'}]);if(page==='bands'){const n=Math.max(0,parseInt(arg)||0),bands=expeditionBands[s.active];return v(s.active==='farm'?'My top-down farm':'Explore world layers','PIP can take you straight to a layer. Or close this panel and travel through the world yourself. Distances are compressed.',[...bands.slice(n*3,n*3+3).map(([label],i)=>({label,type:'band',index:n*3+i})),n?go('← Previous layers','bands:'+(n-1)):go('← PIP','mission'),...(bands.length>(n+1)*3?[go('More layers →','bands:'+(n+1))]:[])]);}if(page==='last'){const item=w.last||w.seen.at(-1),data=item?expeditionItems[item.type]:null;return v(data?data.name:'My discoveries',data?data.fact:'Tap a colored discovery cube. Its record will be kept in your journal.',[go('🤖 My trail goal','mission'),go('🌍 Choose a world','home')]);}if(page==='gear')return v('My exploration backpack','Every astronaut has pop-out wings and boosters. Fold them for walking, gravity and automatic hops or climbs. Swim assistance stays on underwater.',[{label:w.fly?'Fold wings / boosters':'Deploy wings / boosters',type:'flight'},{label:'🧑‍🚀 Choose my astronaut',type:'crew'},go('🧱 Build blocks','build'),go('🔎 Inspect a discovery','last'),go('🌍 World options','options')]);if(page==='farm-help')return v('My top-down farm','Tap a brown soil tile. Choose an owned seed, water it, then explore another world. Return here for the next growth stage. Grown plants can be harvested.',[go('🌍 Explore another world','home'),go('🤖 My trail goal','mission'),{label:'🏠 Return home',type:'exit'}]);if(page==='plot'){const p=w.plots[w.selectedPlot],name=p?farmPlants.find(f=>f.id===p.seed)?.name:'';return v(p?name+' / '+['Seed','Sprout','Young plant','Grown plant'][p.stage]:'My planting bed',p?(p.stage===3?'A grown plant. You can harvest or choose another seed.':p.watered?'Watered! Explore and return for the next growth stage.':'This plant is ready for water.'):'Choose a seed from your shared seed bank.',[...(!p||p.stage===3?[go('🌱 Choose my seed','seeds:0')]:[{label:p.watered?'✓ Watered':'💧 Water this plant',type:'water'}]),...(p?.stage===3?[{label:p.harvested?'↻ Collect again':'🧺 Harvest',type:'harvest'}]:[]),go('🌍 Explore / return later','home'),go('🤖 Farm help','farm-help')]);}if(page==='seeds'){const n=Math.max(0,parseInt(arg)||0),plants=ctx.plants||[];return v('My seed bank',plants.length?'Tap an owned seed. Seeds are reusable in this training farm.':'Find a seed in the forest, or visit the home farm seed bank.',[...plants.slice(n*3,n*3+3).map(p=>({label:p.icon+' '+p.name,type:'plant',seed:p.id})),n?go('← Previous seeds','seeds:'+(n-1)):go('← My planting bed','plot'),...(plants.length>(n+1)*3?[go('More seeds →','seeds:'+(n+1))]:[])]);}return expeditionView(s,'home',ctx);}
export function expeditionJournal(s,section){const out=[];for(const [mode,w]of Object.entries(s.worlds)){if(section==='found')for(const item of w.seen){const d=expeditionItems[item.type];out.push({id:'exp-'+item.id,title:item.seed?(farmPlants.find(p=>p.id===item.seed)?.name||'Plant')+' seed':d.name,icon:expeditionModes[mode].icon,summary:'I explored '+expeditionModes[mode].name+'.',fact:d.fact,target:'grounds-home',expeditionMode:mode,expeditionFocus:{x:item.x,y:item.y}});}if(section==='adventures'){for(const i of w.bands)out.push({id:'exp-band-'+mode+'-'+i,title:expeditionBands[mode][i][0],icon:expeditionModes[mode].icon,summary:'I visited this layer in our not-to-scale exploration model.',fact:expeditionBands[mode][i][3],target:'grounds-home',expeditionMode:mode,expeditionFocus:{x:w.x,y:mode==='farm'?w.y:(expeditionBands[mode][i][1]+expeditionBands[mode][i][2])/2*40}});if(w.mission===3)out.push({id:'exp-mission-'+mode,title:'My '+expeditionModes[mode].name+' trail',icon:'🧭',summary:'I followed the trail goal and returned to PIP camp.',fact:'I can repeat this mission or keep exploring freely.',target:'grounds-home',expeditionMode:mode});}if(section==='experiments')for(const seed of w.harvested)out.push({id:'exp-harvest-'+seed,title:'I grew '+farmPlants.find(p=>p.id===seed).name+'.',icon:'🌱',summary:'I planted, watered, returned and harvested in my open farm.',fact:'This is a visit-based growth model, not real plant growth speed.',target:'grounds-home',expeditionMode:'farm'});}return out;}
export function expeditionCellSvg(type){const color=expeditionPalette[type]||expeditionPalette.air;let a=`<rect width="40" height="40" fill="${color}"/><path d="M0 39h40M39 0v40" stroke="#17384a" stroke-opacity=".12"/>`;if(type==='platform'||type==='branch')a='<rect y="0" width="40" height="12" fill="#9a7951"/>';if(type==='ladder')a='<rect width="40" height="40" fill="#c2dfe2"/><path d="M10 0v40m20-40v40M10 8h20M10 20h20M10 32h20" stroke="#7f816d" stroke-width="4"/>';if(type.startsWith('crop')){const stage=+type[4],size=[5,12,23,32][stage];a=`<rect width="40" height="40" fill="#a78059"/><rect x="${20-size/2}" y="${20-size/2}" width="${size}" height="${size}" fill="${color}" stroke="#17384a" stroke-width="2"/>`+(stage===3?'<rect x="23" y="10" width="7" height="7" fill="#dc9c65"/>':'');}if(type.endsWith('wet'))a+='<path d="M32 3l5 7-5 5-5-5z" fill="#35d3c9" stroke="#17384a" stroke-width="1"/>';return `<svg xmlns="http://www.w3.org/2000/svg" width="40" height="40">${a}</svg>`;}

export function expeditionPlace(s,point){const w=s.worlds[s.active],x=Math.floor(point.x/40),y=Math.floor(point.y/40),key=expKey(x,y);if(w.tool==='remove'){delete w.blocks[key];return 'Your block was put away.';}if(!['block','platform','ladder'].includes(w.tool))return '';if(Math.abs(w.x-(x*40+20))<30&&w.y>y*40&&w.y<y*40+100)return 'Choose a clear cell beside your astronaut.';if(!w.blocks[key]&&Object.keys(w.blocks).length>=2048)return 'This saved trail has 2048 blocks. Reuse a piece or keep exploring.';w.blocks[key]=w.tool;return 'Placed '+w.tool+'.';}
export function expeditionRevisit(s,mode,focus){expeditionEnter(s,mode);const w=s.worlds[mode];if(focus&&Number.isFinite(focus.x)&&Number.isFinite(focus.y)){w.x=expClamp(focus.x,-1e12,1e12);w.y=mode==='farm'?expClamp(focus.y,-1e12,1e12):expClamp(focus.y,40,expeditionModes[mode].height*40-45);if(mode==='cave'){const [x,y]=expFootCell(w);expDig(w,x,y,true);w.gripping=true;}if(mode==='sky'||mode==='forest'&&w.y<39*40)w.fly=true;}return w;}

export function expeditionSuitVisual(d,fly,mode){return {...d,parts:{...d.parts,back:mode==='ocean'||!fly?'thrusters':'both'}};}
